**JavaScript (in a separate file `pendulum.js`):**
```javascript
// Constants
const GRAVITY = 9.8; // m/s^2
const PENDULUM_LENGTH = 20; // meters

// Initial state
let angle = 0;
let velocity = 0;
let time = 0;

// Pendulum object
class Pendulum {
  constructor() {
    this.element = document.getElementById("pendulum");
    this.element.style.transform = `rotate(${angle}deg)`;
  }

  updateAngle() {
    // Calculate the new angular velocity
    velocity += (-angle * GRAVITY * Math.sin(angle) / PENDULUM_LENGTH) * time;
    angle += velocity * time;

    // Update the pendulum's position
    this.element.style.transform = `rotate(${angle}deg)`;
  }
}

// Create the pendulum object
const pendulum = new Pendulum();

// Event handlers
document.getElementById("release-button").addEventListener("click", () => {
  angle = parseFloat(document.getElementById("initial-angle").value);
  velocity = 0;
  time = 0;
  pendulum.updateAngle();
  setInterval(() => {
    pendulum.updateAngle();
    time += 0.01; // Update at 10 Hz
  }, 10);
});
```
**How it works:**

