import com.fasterxml.jackson.databind.JsonToken;
import com.google.gson.Gson;

public class JwtDecoder {
    public static String.getTokenPayload(String token) {
        String[] parts = token.split("\\.");
        if (parts.length < 3) {
            throw new RuntimeException("Invalid token");
        }
        String base64EncodedHeader = parts[0];
        String base64EncodedPayload = parts[1];
        String base64EncodedSignature = parts[2];

        // Decode the header and payload
