        JsonToken jsonToken = JsonToken.valueOf(decodedPayload);
        TokenPayload tokenPayload = gson.fromJson(jsonToken, TokenPayload.class);

        return tokenPayload.toString();
    }
}

class TokenPayload {
    private String userId;
    private String role;

    public String getUserId() {
        return userId;
    }

    public String getRole() {
        return role;
    }
}
