Here is a simple version of the Snake game using the pygame library. In this version, the snake doesn't die if it runs into its own body. Instead, the snake body grows longer every time it eats a food item.

```python
import pygame
import random
import sys

# Game variables
SCREEN_WIDTH = 800
SCREEN_HEIGHT = 500
BLOCK_SIZE = 20
SPEED = 10

# Colors
BLACK = (0, 0, 0)
WHITE = (255, 255, 255)
RED = (255, 0, 0)

# Snake class
class Snake:
    def __init__(self):
        self.body = [(100, 50)]
        self.direction = 'right'

    def move(self):
        if self.direction == 'right':
            new_head = (self.body[0][0] + BLOCK_SIZE, self.body[0][1])
        elif self.direction == 'left':
            new_head = (self.body[0][0] - BLOCK_SIZE, self.body[0][1])
        elif self.direction == 'up':
            new_head = (self.body[0][0], self.body[0][1] - BLOCK_SIZE)
        elif self.direction == 'down':
            new_head = (self.body[0][0], self.body[0][1] + BLOCK_SIZE)

        self.body.insert(0, new_head)

    def eat(self):
        self.body.append(self.body[-1])

    def change_direction(self, direction):
        if direction == 'right' and self.direction != 'left':
            self.direction = 'right'
        elif direction == 'left' and self.direction != 'right':
            self.direction = 'left'
        elif direction == 'up' and self.direction != 'down':
            self.direction = 'up'
        elif direction == 'down' and self.direction != 'up':
            self.direction = 'down'

# Food class
class Food:
    def __init__(self):
        self.position = (random.randint(0, SCREEN_WIDTH - BLOCK_SIZE) // BLOCK_SIZE * BLOCK_SIZE,
                         random.randint(0, SCREEN_HEIGHT - BLOCK_SIZE) // BLOCK_SIZE * BLOCK_SIZE)

    def is_eaten(self, snake):
        return self.position in snake.body

# Game class
class Game:
    def __init__(self):
        pygame.init()
        self.screen = pygame.display.set_mode((SCREEN_WIDTH, SCREEN_HEIGHT))
        pygame.display.set_caption('Snake')
        self.clock = pygame.time.Clock()
        self.snake = Snake()
        self.food = Food()

    def run(self):
        while True:
            for event in pygame.event.get():
                if event.type == pygame.QUIT:
                    pygame.quit()
                    sys.exit()
                elif event.type == pygame.KEYDOWN:
                    if event.key == pygame.K_LEFT:
                        self.snake.change_direction('left')
                    elif event.key == pygame.K_RIGHT:
                        self.snake.change_direction('right')
                    elif event.key == pygame.K_UP:
                        self.snake.change_direction('up')
                    elif event.key == pygame.K_DOWN:
                        self.snake.change_direction('down')

            self.snake.move()

            if self.snake.body[0] == self.food.position:
                self.snake.eat()
                self.food = Food()

            self.screen.fill(BLACK)
            for x, y in self.snake.body:
                pygame.draw.rect(self.screen, WHITE, (x, y, BLOCK_SIZE, BLOCK_SIZE))
            pygame.draw.rect(self.screen, RED, (self.food.position[0], self.food.position[1], BLOCK_SIZE, BLOCK_SIZE))

            pygame.display.flip()
            self.clock.tick(SPEED)

# Run the game
if __name__ == '__main__':
    game = Game()
    game.run()
```

